// Распарсиваем строку, как ты и делал. Это правильно для твоего флоу.
const dealDataString = items[0].json.data;
const deal = JSON.parse(dealDataString);

// --- Собираем все данные, которые тебе были нужны раньше ---
const dealId = deal.id || null;
const responsibleUserId = deal.responsible_user_id || null;

let courseValue = null;
if (deal.custom_fields_values) {
    const courseField = deal.custom_fields_values.find(f => f.field_name === "Курс");
    if (courseField && courseField.values && courseField.values.length > 0) {
        courseValue = courseField.values[0].value;
    }
}

// 🔥 А вот и главное изменение:
// Собираем ID ВСЕХ контактов ("пеналов") в один массив (список)
const contactIds = (deal._embedded?.contacts || []).map(c => c.id);

// --- Возвращаем ОДИН "пакет" со ВСЕМИ данными для следующего шага ---
return [{
    json: {
        dealId: dealId,
        responsibleID: responsibleUserId,
        course: courseValue,
        // Добавляем наш новый массив с ID контактов.
        // Он будет выглядеть примерно так: [12345, 67890]
        contactIds: contactIds
    }
}];

// Код полностью заменяет содержимое узла Code3 (создание примечания в AmoCRM)

return {
  json: {
    dealId: $('Edit Fields').first().json.dealId,
    notes: [
      {
        note_type: "common",
        params: {
          text: `**Анализ звонка:** 🔥
${$input.first().json.expertComment || $input.first().json.message?.content || "—"}

**Оценки:**
Контекст — ${$input.first().json.ratings?.["Контекст"] ?? "-"}
Попытка закрытия — ${$input.first().json.ratings?.["Попытка закрытия на оплату"] ?? "-"}
Возражения — ${$input.first().json.ratings?.["Работа с возражениями через контекст"] ?? "-"}
Срочность — ${$input.first().json.ratings?.["Усиление боли / FOMO / срочности"] ?? "-"}
Шаг и срок оплаты — ${$input.first().json.ratings?.["Договорённость по шагу и сроку оплаты"] ?? "-"}

**Длительность звонка:** ${$('Edit Fields').first().json.callDuration || "?"} секунд`
        }
      }
    ]
  }
};

const allNotes = [];
let dealData = null;

// Проходим по всем пакетам, которые пришли на вход в Code2
for (const item of items) {
  // Проверяем, есть ли поле 'data'. Это данные с заметками.
  if (item.json.data) {
    try {
      const parsedData = JSON.parse(item.json.data);
      const notes = parsedData._embedded?.notes || [];
      allNotes.push(...notes);
    } catch (e) {
      console.error("Failed to parse JSON from 'data' field:", e);
    }
  } 
  // Проверяем, есть ли dealId. Это данные сделки.
  else if (item.json.dealId) {
    dealData = item.json;
  }
}

let longestCall = null;
let longestDuration = -1;

// Ищем самый длинный звонок среди всех заметок
for (const note of allNotes) {
    const isCall = note.note_type === 'call_in' || note.note_type === 'call_out';
    const hasLink = note.params && note.params.link;

    if (isCall && hasLink) {
        const duration = note.params.duration;
        if (duration > longestDuration) {
            longestDuration = duration;
            longestCall = note;
        }
    }
}

// Если dealData не найден, создаем пустой объект
if (!dealData) {
    dealData = {};
}

// Возвращаем один пакет, который содержит данные сделки и самого длинного звонка
return [
    {
        json: {
            ...dealData, // Копируем все поля из dealData
            recordUrl: longestCall ? longestCall.params.link : null,
            callDuration: longestCall ? longestCall.params.duration : -1
        }
    }
];

// Получаем текст из поля message.content
let tipText = $input.first().json.message.content || "";

// Убираем markdown-блоки кода, если есть
// tipText = tipText.replace(/```[\s\S]*?```/g, "");

// Заменяем переносы строк на пробелы
// tipText = tipText.replace(/\r?\n+/g, " ");

// Убираем лишние пробелы
// tipText = tipText.replace(/\s+/g, " ").trim();

// Возвращаем как отдельное поле
return [
  {
    json: {
      nextStepTip: tipText
    }
  }
];

